/**
 * The data revision that keys every plan and probe cache must survive a restart: it is derived from the durable LMDB
 * transaction id, never from an in-memory counter that restarts at zero and is then masked by the persisted synopsis
 * version.
 */
class LmdbDataRevisionRestartTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI A = VF.createIRI("urn:a");
	private static final IRI B = VF.createIRI("urn:b");
	private static final IRI C = VF.createIRI("urn:c");

	@Test
	void dataRevisionIsMonotonicAcrossReopen(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		long beforeClose;
		try (TripleStore store = new TripleStore(dataDir, config, null)) {
			long opened = store.getDataRevision();
			store.startTransaction();
			store.storeTriple(1, 2, 3, 1, true);
			store.commit();
			long first = store.getDataRevision();
			store.startTransaction();
			store.storeTriple(1, 2, 4, 1, true);
			store.commit();
			beforeClose = store.getDataRevision();

			assertTrue(first > opened, "a commit must advance the data revision: " + opened + " -> " + first);
			assertTrue(beforeClose > first, "every commit advances the data revision: " + first + " -> "
					+ beforeClose);
		}
		try (TripleStore reopened = new TripleStore(dataDir, config, null)) {
			long afterReopen = reopened.getDataRevision();
			assertTrue(afterReopen >= beforeClose, "the data revision must not restart below its persisted value: "
					+ beforeClose + " -> " + afterReopen);

			reopened.startTransaction();
			reopened.storeTriple(1, 2, 5, 1, true);
			reopened.commit();

			assertTrue(reopened.getDataRevision() > afterReopen,
					"the first post-restart commit must be distinguishable from the pre-restart state");
		}
	}

	@Test
	void snapshotVersionIgnoresSynopsisVersion() {
		TripleStore tripleStore = mock(TripleStore.class);
		LmdbQuadSynopsisService synopsis = mock(LmdbQuadSynopsisService.class);
		when(tripleStore.getDataRevision()).thenReturn(1L);
		when(synopsis.snapshotVersion()).thenReturn(4L);
		LmdbEstimatorRuntime runtime = new LmdbEstimatorRuntime(null, tripleStore, synopsis, null, null, null, null);

		assertEquals(1L, runtime.snapshotVersion(),
				"the data identity must follow the store's data revision, not the persisted synopsis version");

		when(tripleStore.getDataRevision()).thenReturn(2L);
		assertEquals(2L, runtime.snapshotVersion(), "a commit must move the data identity");
	}

	@Test
	void synopsisPublishMovesFrontierRevisionNotTheDataIdentity() {
		TripleStore tripleStore = mock(TripleStore.class);
		LmdbQuadSynopsisService synopsis = mock(LmdbQuadSynopsisService.class);
		when(tripleStore.getDataRevision()).thenReturn(9L);
		when(synopsis.snapshotVersion()).thenReturn(4L);
		LmdbEstimatorRuntime runtime = new LmdbEstimatorRuntime(null, tripleStore, synopsis, null, null, null, null);
		long dataBefore = runtime.snapshotVersion();
		long frontierBefore = runtime.frontierPlanningRevision();

		when(synopsis.snapshotVersion()).thenReturn(5L);

		assertEquals(dataBefore, runtime.snapshotVersion(), "a synopsis rebuild is evidence, not data");
		assertNotEquals(frontierBefore, runtime.frontierPlanningRevision(),
				"a synopsis rebuild must still refresh plan evidence through the frontier revision");
	}

	@Test
	void packedCacheAfterRestartMustNotServeRangeEmptyProofAfterCommit(@TempDir File dataDir) {
		assertRestartedPackedCacheFresh(dataDir, true);
	}

	@Test
	void packedCacheWithoutRestartControl(@TempDir File dataDir) {
		assertRestartedPackedCacheFresh(dataDir, false);
	}

	@Test
	void pipelineAnchoredPlanReplansAfterFirstPostRestartCommit(@TempDir File dataDir) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(true)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		String query = "SELECT ?s WHERE { ?s <urn:p> ?o FILTER(?o = 7) }";
		SailRepository repository = repository(dataDir, config);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			connection.add(B, P, VF.createLiteral("6", XSD.INTEGER));
			var estimator = ((LmdbStore) repository.getSail()).getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			for (int i = 0; i < 4; i++) {
				estimator.rebuild();
			}
		}
		repository.shutDown();
		repository = repository(dataDir, config);
		try (RepositoryConnection connection = repository.getConnection()) {
			((LmdbStore) repository.getSail()).getBackingStore().getSketchBasedJoinEstimator().stop();
			assertEquals(Set.of(), rows(connection, query, "s"));
			assertEquals(Set.of(), rows(connection, query, "s"));

			connection.add(C, P, VF.createLiteral("7", XSD.INTEGER));

			// The first post-restart commit must move the data revision, so the anchored plan (a hard
			// committed-snapshot dependency) is replanned instead of served from the cache.
			TupleExpr replanned = explain(connection, query);
			assertNotEquals("true", replanned.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"),
					"the pre-commit anchored plan must not be served unchanged after the commit");
			assertEquals(Set.of("urn:c"), rows(connection, query, "s"),
					"a committed value-equal term must be visible after the first post-restart commit");
			// The replacement plan built at the new data revision replaces the stale family version and is served
			// from the cache again.
			TupleExpr replacement = explain(connection, query);
			assertEquals("true", replacement.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"),
					"the replacement plan must be publishable after the hard-dependency replan");
			assertEquals("USE", replacement.getStringMetricPlanned("optimizer.planCacheLookupOutcome"));
		} finally {
			repository.shutDown();
		}
	}

	private static void assertRestartedPackedCacheFresh(File dataDir, boolean restart) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(true)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		String query = "SELECT ?s WHERE { ?s <urn:p> 7 }";
		SailRepository repository = repository(dataDir, config);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			connection.add(B, P, VF.createLiteral("6", XSD.INTEGER));
			var estimator = ((LmdbStore) repository.getSail()).getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			for (int i = 0; i < 4; i++) {
				estimator.rebuild();
			}
		}
		if (restart) {
			repository.shutDown();
			repository = repository(dataDir, config);
		}
		try (RepositoryConnection connection = repository.getConnection()) {
			((LmdbStore) repository.getSail()).getBackingStore().getSketchBasedJoinEstimator().stop();
			assertEquals(Set.of(), rows(connection, query, "s"));

			connection.add(C, P, VF.createLiteral("7", XSD.INTEGER));
			Set<String> afterCommit = rows(connection, query, "s");

			assertEquals(Set.of("urn:c"), afterCommit, "committed :c :p 7 must be visible (restart=" + restart + ")");
		} finally {
			repository.shutDown();
		}
	}

	private static SailRepository repository(File dataDir, LmdbStoreConfig config) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, config));
		repository.init();
		return repository;
	}

	private static Set<String> rows(RepositoryConnection connection, String query, String... names) {
		Set<String> rows = new TreeSet<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			for (BindingSet bindingSet : result) {
				StringBuilder row = new StringBuilder();
				for (int index = 0; index < names.length; index++) {
					if (index > 0) {
						row.append('|');
					}
					row.append(bindingSet.getValue(names[index]) == null ? "UNBOUND"
							: bindingSet.getValue(names[index]).stringValue());
				}
				rows.add(row.toString());
			}
		}
		return rows;
	}

	private static TupleExpr explain(RepositoryConnection connection, String query) {
		return (TupleExpr) connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized).tupleExpr();
	}
}
